class ProcessStageSchema(BaseModel):
    index: Optional[conint(ge=1)] = None
    """
    Order of the stage within the process, starting at 1.
    """
    categories: Union[SynthesisTechniqueCategorySchema1, CharacterizationTechniqueCategorySchema1]
    """
    Technique this stage applies.
    """
    sources: Optional[List[ProcessSourceSchema]] = None
    """
    Material sources available to the steps of this stage: sputtering targets, precursors, process gases.
    """
    environment: Optional[EnvironmentSchema] = Field(None, title="environment schema")
    """
    Ambient or chamber conditions during a measurement or a process step.
    """
    parameters: Optional[Dict[str, Any]] = None
    """
    Technique-specific parameters. Unconstrained here, the way a model's parameters are unconstrained until a models_directory entry narrows them; technique blocks such as measurement/parameters/scanning_probe_microscopy describe the expected shape and will be bound per technique by catalogue entries in a later phase.
    """
    steps: List[ProcessStepSchema]
    """
    Ordered steps of the stage, the analogue of a subworkflow's units.
    """
    duration: Optional[TimeQuantitySchema1] = Field(None, title="time quantity schema")
    """
    A scalar with time units, e.g. a process step duration. Follows the core/reusable/energy pattern (a scalar plus a units enum) without requiring a property name, so it can be embedded as a field of any schema.
    """
    notes: Optional[str] = None
    """
    Operator notes, kept verbatim: laboratory records carry context that no schema anticipates.
    """
    id: Optional[str] = Field(None, alias="_id")
    """
    entity identity
    """
    slug: Optional[str] = None
    """
    entity slug
    """
    systemName: Optional[str] = None
    schemaVersion: Optional[str] = "2022.8.16"
    """
    entity's schema version. Used to distinct between different schemas.
    """
    name: str
    """
    entity name
    """
    instrument: Optional[InstrumentSchema] = Field(None, title="instrument schema")
    """
    A physical apparatus used to measure or fabricate a sample: a microscope, a deposition chamber, a furnace. The experimental mirror of software/application, composed the same way, because what an application is to a job an instrument is to a measurement.
    """
    status: Optional[Status4] = None
    """
    Lifecycle state. 'draft' marks a recipe or protocol that has not been executed.
    """
    startTime: Optional[datetime] = None
    """
    When the activity started, as an ISO 8601 timestamp. A string rather than an epoch number so it stays readable without a converter, matching job.startTime.
    """
    endTime: Optional[datetime] = None
    """
    When the activity finished, as an ISO 8601 timestamp.
    """
    operators: Optional[List[Operator]] = None
    """
    People who ran the activity. A name and an optional affiliation rather than the bibliographic author shape used for citations: a laboratory record identifies an operator by whatever the instrument logged, often a single username, and a citation's requirement of a surname does not hold there.
    """
    project: Optional[EntityReferenceSchema] = Field(None, alias="_project", title="entity reference schema")


