class BaseProcessSchema(BaseModel):
    categories: Union[SynthesisTechniqueCategorySchema, CharacterizationTechniqueCategorySchema]
    """
    Technique this process applies. A measurement protocol is a process with characterization categories, which is why both branches are allowed; anyOf rather than oneOf because a record classified only to tier1 satisfies both and must not be rejected as ambiguous.
    """
    properties: Optional[List[str]] = None
    """
    Array of characteristic properties produced by this process, by name, e.g. film_thickness
    """
    stages: List[ProcessStageSchema]
    """
    Ordered stages, the analogue of workflow.subworkflows. A stage is the level that binds a technique and an instrument, because a run can move between chambers.
    """
    inputSamples: Optional[List[SampleEntityReferenceSchema]] = Field(None, alias="_inputSamples")
    """
    Subsets of the full information about the samples consumed, e.g. the substrates loaded into the chamber.
    """
    outputSamples: Optional[List[SampleEntityReferenceSchema2]] = Field(None, alias="_outputSamples")
    """
    Subsets of the full information about the samples produced or modified by the run.
    """
    identifiers: Optional[List[IdentifierSchema]] = None
    """
    Identifiers this run carries in other systems, e.g. a lab-system run number.
    """
    logFiles: Optional[List[FileReferenceSchema]] = None
    """
    Tool logs this record was derived from.
    """
    status: Optional[Status4] = None
    """
    Lifecycle state. 'draft' marks a recipe or protocol that has not been executed.
    """
    startTime: Optional[datetime] = None
    """
    When the activity started, as an ISO 8601 timestamp. A string rather than an epoch number so it stays readable without a converter, matching job.startTime.
    """
    endTime: Optional[datetime] = None
    """
    When the activity finished, as an ISO 8601 timestamp.
    """
    operators: Optional[List[Operator2]] = None
    """
    People who ran the activity. A name and an optional affiliation rather than the bibliographic author shape used for citations: a laboratory record identifies an operator by whatever the instrument logged, often a single username, and a citation's requirement of a surname does not hold there.
    """
    project: Optional[EntityReferenceSchema] = Field(None, alias="_project", title="entity reference schema")
